const root=document.querySelector('#app'),key='petverso-v1';let scene='living',bathStep=0,bathProgress=0,waterOn=false,soapSelected=false,strokeDistance=0;let pet=null,collection=null,page='home',family='all',message='',activity='idle',game=null,cleanup=()=>{},surprise=false,pendingSpecies=null,pendingColor=0;
try{const raw=JSON.parse(localStorage.getItem(key));collection=normalizeCollection(raw);pet=activePet(collection);if(pet)scene=pet.sleeping?'bedroom':'living';}catch{}
