const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function petDialog({title,message,confirmLabel='Confirmar',cancelLabel='Cancelar',danger=false,inputValue=null}){
 return new Promise(resolve=>{const previous=document.activeElement,overlay=document.createElement('div');overlay.className='overlay pet-dialog-overlay';overlay.innerHTML=`<section class="dialog pet-dialog" role="dialog" aria-modal="true" aria-labelledby="pet-dialog-title"><div class="pet-dialog-mark">${danger?'!':'♥'}</div><h2 id="pet-dialog-title">${esc(title)}</h2><p>${esc(message)}</p>${inputValue!==null?`<label class="pet-dialog-label">Nome do pet<input class="pet-dialog-input" maxlength="24" value="${esc(inputValue)}" autocomplete="off"></label>`:''}<div class="pet-dialog-actions"><button type="button" class="pet-dialog-cancel">${esc(cancelLabel)}</button><button type="button" class="pet-dialog-confirm ${danger?'danger':''}">${esc(confirmLabel)}</button></div></section>`;document.body.append(overlay);const input=overlay.querySelector('input'),cancel=overlay.querySelector('.pet-dialog-cancel'),confirm=overlay.querySelector('.pet-dialog-confirm'),focusables=()=>[...overlay.querySelectorAll('button,input')];let done=false;
  function close(value){if(done)return;done=true;document.removeEventListener('keydown',keys);overlay.remove();previous?.isConnected&&previous.focus();resolve(value);}
  function submit(){const value=input?input.value.trim():true;if(input&&!value){input.focus();input.classList.add('invalid');return;}close(value);}
  function keys(e){if(e.key==='Escape'){e.preventDefault();close(input?null:false);}if(e.key==='Enter'&&document.activeElement===input){e.preventDefault();submit();}if(e.key==='Tab'){const list=focusables(),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
  cancel.onclick=()=>close(input?null:false);confirm.onclick=submit;overlay.onclick=e=>{if(e.target===overlay)close(input?null:false);};document.addEventListener('keydown',keys);(input||cancel).focus();input?.select();
 });
}
const petConfirm=(title,message,confirmLabel='Confirmar',danger=false)=>petDialog({title,message,confirmLabel,danger});
const petPrompt=(title,message,value='')=>petDialog({title,message,inputValue:value,confirmLabel:'Salvar'});

