function garden(s){const slots=['garden-swing','garden-slide','garden-trampoline','garden-bench'];return `<section class="room world garden ${pet.sleeping?'night':''}"><div class="park-background">${environmentArt(environmentFor(s.id).id,{night:pet.sleeping,tall:true})}</div><button class="park-navigation park-next" data-scene="playground" aria-label="Ir ao Parquinho">Parquinho <span aria-hidden="true">›</span></button>${slots.map(slot=>{const id=pet.equipped?.[slot];return id?`<div class="garden-item ${slot}">${paintFurniture(id)}</div>`:'';}).join('')}<div class="pet-stage garden-pet ${['sombrios-0','sombrios-1','sombrios-dragon','dinos-pterosaur','selva-owl'].includes(s.id)?'airborne':'grounded'} ${pet.sleeping?'resting-away':'roaming'}" id="touch-pet" tabindex="0" role="button" aria-label="Faça carinho no pet"><div class="pet-facing">${drawing(s,activity,!pet.sleeping)}</div><div class="hearts"></div></div><span class="room-caption">${pet.sleeping?'Seu pet está dormindo no quarto.':'Um quintal para brincar e decorar!'}</span></section>`;}
