function poop(i){return `<button class="poop poop-${i}" data-poop aria-label="Recolher necessidade"><svg viewBox="0 0 60 60"><path d="M30 5q14 12 1 17c20-1 25 15 9 19 24 3 20 15-10 15S-14 45 8 41C-4 28 15 18 23 21q-1-10 7-16" fill="#9b5e35" stroke="#7c4526" stroke-width="2"/></svg></button>`;}
function room(s,bed,decor,toy,rug){const sleeping=pet.sleeping&&scene==='bedroom',bath=scene==='bathroom',bathActive=bath&&!pet.sleeping;return `<section class="room world ${scene} ${pet.sleeping?'night':''} ${activity==='medicine'?'medicine-active':''}"><div class="wall-pattern"></div><div class="scenery-window"><div class="landscape"><i></i><i></i><span>${icon(pet.sleeping?'skyMoon':'sun')}</span></div><div class="window-frame"></div></div><div class="floor"></div>${scene==='living'?Array.from({length:pet.floorDirt??pet.waste??0},(_,i)=>`<div class="floor-dirt dirt-${i}" aria-label="Chão sujo"></div>`).join(''):''}${bathActive?'<div class="bath-shelf"><svg viewBox="0 0 40 60" width="35" height="50"><path d="M15 5h17v5H23v8H15z" fill="#f6be55"/><rect x="8" y="17" width="24" height="38" rx="7" fill="#7fd8cc"/><path d="M13 30h14v13H13z" fill="#fff4dc"/></svg></div><button id="bath-shower" class="shower" aria-label="Usar chuveiro">'+showerArt+'</button><button id="bath-soap" class="soap-tool" aria-label="Pegar sabonete">'+icon('soap')+'</button>':''}${scene==='bedroom'?`<div class="sleep-bed ${bed?.id||'basic'}">${paintFurniture(bed?.id||'bed-basic',sleeping?'back':'all')}</div>${["left","right"].map(side=>`<div class="bedside-dresser bedside-${side}">${paintFurniture(pet.equipped?.dresser||"dresser-basic")}</div><button class="bedside-lamp bedside-${side} ${bedroomLights[side]?"lit":""}" data-bedside-light="${side}" aria-label="${bedroomLights[side]?"Apagar":"Acender"} abajur ${side==="left"?"esquerdo":"direito"}" aria-pressed="${bedroomLights[side]}">${paintFurniture(pet.equipped?.lamp||"lamp-basic")}</button>`).join("")}`:''}${scene==='living'?livingFurniture():''}${scene==='living'?`<div class="world-decor">${decor?icon(decor.id):''}</div><div class="play-rug ${rug?'rainbow':''}">${paintFurniture(rug?.id||'rug-basic')}</div><div class="world-toy">${toy?icon(toy.id):''}</div>`:''}${bathActive?bathScene(drawing(s,activity),bathStep,pet.equipped?.tub,pet.itemColors?.[pet.equipped?.tub||'tub-basic']):bath?bathScene('',0,pet.equipped?.tub,pet.itemColors?.[pet.equipped?.tub||'tub-basic']):`<div class="pet-stage ${['sombrios-0','sombrios-1','sombrios-dragon','dinos-pterosaur','selva-owl'].includes(s.id)?'airborne':'grounded'} ${sleeping?'in-bed':'roaming'} ${pet.sleeping&&!sleeping?'resting-away':''}" id="touch-pet" tabindex="0" role="button" aria-label="Faça carinho passando o dedo sobre o pet"><div class="pet-facing">${drawing(s,sleeping?'sleep':activity,!pet.sleeping)}</div><div class="hearts"></div>${activity==='medicine'?medicineAnimation():''}</div>`}${sleeping?`<div class="pet-blanket" aria-label="Cobertinha"><svg viewBox="0 0 100 60"><path d="M8 10Q45 0 86 12l6 35Q48 59 8 45Z" fill="#a8dce7" stroke="#77b9cc" stroke-width="2"/><path d="M13 15q36-9 68 1" fill="none" stroke="#e4f9fc" stroke-width="4" stroke-linecap="round"/><path d="M25 25v14M42 22v18M60 25v14M76 27v10" stroke="#cceef3" stroke-width="3" stroke-linecap="round"/></svg></div><div class="sleep-cover">${paintFurniture(bed?.id||'bed-basic','front')}</div>`:''}${scene==='living'?Array.from({length:pet.waste??0},(_,i)=>poop(i)).join(''):''}<span class="room-caption">${bathActive?['Arraste o chuveiro até mim','Passe o sabonete em mim','Enxágue com o chuveiro','Banho completo!'][bathStep]:bath&&pet.sleeping?'O banheiro está livre. Seu pet está descansando no quarto.':sleeping?'Dormindo na caminha. Zzz…':pet.sleeping?'Seu pet está dormindo no quarto.':pet.ill?'Preciso de cuidados para ficar bem.':''}</span></section>${bathActive?`<div class="bath-controls" aria-live="polite"><div class="bath-steps">${[['energy','Molhar'],['bath','Ensaboar'],['bath','Enxaguar']].map(([i,label],index)=>`<span class="${bathStep>index?'done':bathStep===index?'current':''}">${bathStep>index?'✓':index+1} ${label}</span>`).join('')}</div><p>${bathStep===3?'Prontinho!':bathStep===1?'Arraste o sabonete sobre o pet.':'Arraste o chuveiro sobre o pet.'}</p></div>`:''}`;}
function useTrick(world){
 const target=world.querySelector('#touch-pet');if(!target||world.dataset.skillBusy==='true'||pet.sleeping||pet.dead)return;
 // Resume Web Audio from the user interaction before playing the species sound.
 audio.unlock();
 if(!startTrick(pet))return;save();world.dataset.skillBusy='true';world.dispatchEvent(new Event('pet-skill-start'));
 const s=species.find(s=>s.id===pet.species),walking=['stretch','sniff','pounce','dash','relax'].includes(tricks[pet.species][0]);
 const previous=sceneCleanup;let ended=false;
 const stop=animateTrick(target,pet.species,{draw:()=>drawing(s,'happy',walking),sound:name=>audio.sound(name),reducedMotion:!audio.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches,onEnd:()=>{ended=true;world.dataset.skillBusy='false';world.dispatchEvent(new Event('pet-skill-end'));}});
 sceneCleanup=()=>{previous();if(!ended)stop();};
}
function useParkAction(world){
 const target=world.querySelector('#touch-pet');if(!target||world.dataset.skillBusy==='true'||!startParkAction(pet))return;
 save();world.dataset.skillBusy='true';world.dispatchEvent(new Event('pet-skill-start'));const previous=sceneCleanup;let ended=false;
 const stop=animateParkAction(world,target,pet.species,{level:growthProgress(pet).level,reducedMotion:!audio.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches,onEnd:()=>{ended=true;world.dataset.skillBusy='false';world.dispatchEvent(new Event('pet-skill-end'));}});
 sceneCleanup=()=>{previous();if(!ended)stop();};
}
function updateSkillBadge(world){const b=world.querySelector('.skill-badge');if(!b)return;const left=scene==='living'?trickState(pet).remaining:parkActionState(pet).remaining,box=document.createElement('div');box.innerHTML=skillBadge(pet,scene,left);b.className=box.firstChild.className;b.innerHTML=box.firstChild.innerHTML;b.setAttribute('aria-disabled',box.firstChild.getAttribute('aria-disabled'));b.setAttribute('aria-label',box.firstChild.getAttribute('aria-label'));}
function bindScene(){
 if(pet?.dead)return;
 root.querySelectorAll('[data-bedside-light]').forEach(button=>{button.onclick=e=>{e.stopPropagation();const side=button.dataset.bedsideLight;bedroomLights[side]=!bedroomLights[side];button.classList.toggle('lit',bedroomLights[side]);button.setAttribute('aria-pressed',String(bedroomLights[side]));button.setAttribute('aria-label',`${bedroomLights[side]?'Apagar':'Acender'} abajur ${side==='left'?'esquerdo':'direito'}`);};});
 if(['garden','playground'].includes(scene)&&pet&&!pet.sleeping&&!pet.dead){pet.social={...pet.social,outdoors:Date.now()};save();}
 const world=root.querySelector('.world');if(world&&['living','playground'].includes(scene)){world.insertAdjacentHTML('beforeend',skillBadge(pet,scene,scene==='living'?trickState(pet).remaining:parkActionState(pet).remaining));world.querySelector('.skill-badge').onclick=()=>{const required=scene==='playground'?75:50;if(pet.stats.intelligence<required){if(!skillNoticeShown){skillNoticeShown=true;notify(`🧠 ${Math.floor(pet.stats.intelligence)} / ${required} para esta habilidade`,3000);}return;}if(scene==='living')useTrick(world);else useParkAction(world);updateSkillBadge(world);};const prior=sceneCleanup;const refresh=setInterval(()=>updateSkillBadge(world),1000);sceneCleanup=()=>{clearInterval(refresh);prior();};}
 root.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{if(scene==='bathroom'&&b.dataset.scene!==scene)resetBath();scene=b.dataset.scene;render();});
 if(['garden','playground'].includes(scene)){const prior=sceneCleanup,swipe=bindParkSwipe(root.querySelector('.world'),destination=>{if(destination!==scene){scene=destination;render();}});sceneCleanup=()=>{swipe();prior();};}
 root.querySelectorAll('[data-poop]').forEach(b=>b.onclick=()=>{updatePetTime();pet=care(pet,'pickup');audio.sound('clean');save();render();});
 if(pet&&scene==='bathroom'&&!pet.sleeping){sceneCleanup=bindBath({root,audio,step:bathStep,sleeping:pet.sleeping,onStep:step=>{bathStep=step;if(step===3){updatePetTime();pet=care(pet,'bath');save();}render();}});return;}
 const target=root.querySelector('#touch-pet');if(!target)return;
 const previousCleanup=sceneCleanup;const callCleanup=bindCallPet({world:root.querySelector('.world'),target,getPet:()=>pet,scene,drawWalking:()=>drawing(species.find(s=>s.id===pet.species),activity,true),onLocked:()=>{if(!callNoticeShown){callNoticeShown=true;notify(`🧠 ${Math.floor(pet.stats.intelligence)} / 25 para seguir seu toque`,3000);}},onBlocked:()=>notify('Escolha um espaço livre no chão.'),reducedMotion:()=>!audio.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches});const thoughtCleanup=bindPetThoughts({world:root.querySelector('.world'),target,getPet:()=>pet,scene,icon});const turnCleanup=bindDirectionalPet({world,target,getPet:()=>pet,getSpecies:()=>({...species.find(s=>s.id===pet.species),growthLevel:growthProgress(pet).level,palette:palettes[pet.species]?.find(c=>c.id===pet.color),dirty:pet.stats.hygiene<60}),getMode:()=>activity==='idle'?mood():activity,reducedMotion:()=>!audio.preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches});sceneCleanup=()=>{turnCleanup();thoughtCleanup();callCleanup();previousCleanup();};
 let dragging=false,last=null,total=0,lastReward=0;
 function insidePet(x,y){const box=target.getBoundingClientRect(),padX=box.width*.16,padTop=box.height*.1,padBottom=box.height*.14;return x>=box.left+padX&&x<=box.right-padX&&y>=box.top+padTop&&y<=box.bottom-padBottom;}
 function rub(amount,x,y){
  if(pet.sleeping||pet.dead||root.querySelector('.world')?.dataset.skillBusy==='true')return;
  if(scene==='bathroom'){
   if(bathStep!==1||!soapSelected)return;
   bathProgress+=amount;
   const dot=document.createElement('i');dot.className='soap-bubble';const box=target.getBoundingClientRect();dot.style.left=`${x-box.x}px`;dot.style.top=`${y-box.y}px`;target.append(dot);
   if(bathProgress>=45){bathStep=2;soapSelected=false;render();}
  }else{total+=amount;target.classList.add('petted');if(total>=60&&Date.now()-lastReward>1500){lastReward=Date.now();total=0;updatePetTime();pet=care(pet,'pet');audio.sound('pet');save();}}
 }
 function down(e){if(world.dataset.skillBusy==='true'||!insidePet(e.clientX,e.clientY))return;dragging=true;last={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);target.classList.add('being-touched');}
 function move(e){if(!dragging)return;const distance=Math.hypot(e.clientX-last.x,e.clientY-last.y);last={x:e.clientX,y:e.clientY};if(!insidePet(e.clientX,e.clientY))return;if(distance>2)rub(Math.min(20,distance*.6),e.clientX,e.clientY);}
 function up(){if(!dragging)return;dragging=false;last=null;target.classList.remove('being-touched');if(scene!=='bathroom')render();}
 target.onpointerdown=down;target.onpointermove=move;target.onpointerup=target.onpointercancel=up;
 target.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(scene==='bathroom'){if(bathStep!==1)return;soapSelected=true;}const r=target.getBoundingClientRect();rub(60,r.x+r.width/2,r.y+r.height/2);}};

}
function action(a){const autoWoke=updatePetTime();if(a==='sleep'&&autoWoke){save();render();return;}if(a==='bath'){if(pet.sleeping)return notify('Acorde seu pet para tomar banho.');scene='bathroom';bathStep=0;bathProgress=0;waterOn=false;soapSelected=false;render();return;}if(a==='sleep'){resetBath();scene=pet.sleeping?'living':'bedroom';}if(a==='feed'&&pet.coins<5)return notify('Faltam moedas. Brinque para ganhar mais!');if(a==='medicine'&&(pet.coins<12||pet.stats.health>=90))return notify(pet.stats.health>=90?'Está saudável! Remédio só quando precisar.':'Você precisa de 12 moedas.');pet=care(pet,a);if(a==='medicine'&&pet.stats.health>=90){pet.ill=false;healthPopupShown=false;document.querySelector('.pet-health-overlay')?.remove();}audio.sound(a==='sleep'?(pet.sleeping?'sleep':'wake'):a);save();if(a==='medicine')scene='living';activity=a==='feed'?'eat':a==='bath'?'bath':a==='pet'?'happy':a==='medicine'?'medicine':'idle';render();setTimeout(()=>{activity='idle';if(page==='home'&&!game)render();},a==='medicine'?2300:1800);}
const mini=[['memory','🃏','Memória','Encontre os pares.','Inteligência'],['sequence','🎵','Repita a sequência','Observe as cores e repita.','Inteligência'],['food','🍓','Frutas e bombas','Corte as frutas; evite bombas.','Felicidade'],['fruitmerge','🍉','Frutas Crescentes','Junte frutas iguais para fazê-las crescer.','Inteligência'],['runner','🏃','Corrida sem fim','Pule obstáculos e supere seu recorde.','Felicidade'],['puzzle','🧩','Quebra-cabeça','Deslize as peças para montar.','Inteligência'],['hide','🙈','Esconde-esconde','Observe e encontre seu pet.','Inteligência'],['flight','🐦','Voo do pet','Toque para voar entre os obstáculos.','Felicidade'],['words','🔎','Caça-palavras','Descubra palavras escondidas nas letras.','Inteligência'],['blocks','🧱','Blocos do Pet','Complete linhas com peças coloridas.','Inteligência'],['match3','🍓','Combinação de Petiscos','Arraste os petiscos e combine três ou mais.','Inteligência']];
function games(){return `<p class="eyebrow">HORA DE BRINCAR</p><h1>Pequenos desafios.<br>Grandes conquistas.</h1>${!pet.dead&&pet.stats.energy<10?'<p class="notice">Seu pet precisa descansar antes de brincar.</p>':''}<div class="points-summary">${icon('points')} ${pet.totalPoints||0} pontos acumulados</div><section class="game-grid">${mini.map(([id,i,n,d,b])=>`<button class="game-card" data-game="${id}" ${!pet.dead&&pet.stats.energy<10?'disabled':''}><span>${icon(id)}</span><strong>${n}</strong><small>Recorde: ${pet.records?.[id]||0} pontos</small></button>`).join('')}</section>`;}
function shopItemArt(item,color){const svg=item.species?toyArt(item.species):furniture(item.id);return recolorItem(svg,color,item.type||item.id);}
function coinsStore(){return `<h1>Lojinha</h1><div class="ownership-tabs">${[['buy','Comprar'],['owned','Já possui'],['coins','Coins']].map(([id,n])=>`<button data-shop-tab="${id}" class="${id===shopTab?'selected':''}">${n}</button>`).join('')}</div><section class="shop-grid">${[[1000,'1,00'],[2500,'2,50'],[5000,'5,00']].map(([n,price])=>`<article class="shop-card"><span>${icon('coin')}</span><h3>${n.toLocaleString('pt-BR')} moedas</h3><b>R$ ${price}</b><button disabled>Em breve</button></article>`).join('')}</section>`;}
function store(){if(shopTab==='coins')return coinsStore();const available=shop.filter(i=>(!legacyColorItems.has(i.id)||pet.inventory?.includes(i.id))&&(!i.species||i.species===pet.species)&&(shopRoom==='all'||(i.room||(i.slot==='bed'?'bedroom':'living'))===shopRoom)&&ownsItem(pet,i)===(shopTab==='owned'));const item=shop.find(i=>i.id===selectedShopItem&&(!i.species||i.species===pet.species));return `<p class="eyebrow">CONSTRUA SEU CANTINHO</p><h1>Lojinha</h1><div class="ownership-tabs" role="group" aria-label="Itens da loja">${[['buy','Comprar'],['owned','Já possui'],['coins','Coins']].map(([id,label])=>`<button data-shop-tab="${id}" class="${shopTab===id?'selected':''}">${label}</button>`).join('')}</div><div class="shop-tabs">${[['all','Tudo'],['living','Sala'],['bedroom','Quarto'],['garden','Quintal'],['bathroom','Banheiro'],['playground','Parquinho']].map(([id,label])=>`<button data-shop-room="${id}" class="${shopRoom===id?'selected':''}">${label}</button>`).join('')}</div><section class="shop-grid">${available.map(i=>{const owned=ownsItem(pet,i),equipped=pet.equipped?.[i.slot]===i.id||i.price===0&&!pet.equipped?.[i.slot];return `<article class="shop-card"><span>${shopItemArt(i,pet.itemColors?.[i.id])}</span><h3>${i.name}</h3><small class="item-room">${({playground:'Parquinho',garden:'Quintal',bedroom:'Quarto',bathroom:'Banheiro',living:'Sala'})[i.room]||(i.slot==='bed'?'Quarto':'Sala')}</small><b>${owned?(equipped?'Em uso':'Disponível'):icon('coin')+' '+i.price}</b><button data-buy="${i.id}">${owned?'Cores e usar':'Escolher cores'}</button></article>`;}).join('')||'<p class="shop-empty">Nenhum item aqui por enquanto.</p>'}</section>${item?`<div class="item-overlay"><section class="item-dialog" role="dialog" aria-modal="true" aria-labelledby="item-title"><button class="item-close" id="close-item" aria-label="Fechar item">×</button><h2 id="item-title">${item.name}</h2><p class="muted">${item.paint==='full'?'Pintura do móvel inteiro':'Cores nos detalhes · materiais preservados'}</p><div class="item-preview">${shopItemArt(item,selectedItemColor)}</div><div class="item-swatches" role="group" aria-label="Escolha a cor">${itemColors.map(c=>`<button data-item-color="${c.id}" aria-label="${c.name}" aria-pressed="${selectedItemColor===c.id}" style="--swatch:${c.hex}"><i></i><small>${c.name}</small></button>`).join('')}</div><p>${ownsItem(pet,item)?'Todas as cores liberadas!':'Uma compra libera todas as cores.'}</p><button id="confirm-item" class="primary" ${!ownsItem(pet,item)&&pet.coins<item.price?'disabled':''}>${ownsItem(pet,item)?'Salvar cor e usar':`Comprar · ${item.price} moedas`}</button></section></div>`:''}`;}
function bindShop(){
 root.querySelectorAll('[data-shop-tab]').forEach(b=>b.onclick=()=>{shopTab=b.dataset.shopTab;selectedShopItem=null;render();});
 root.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{selectedShopItem=b.dataset.buy;selectedItemColor=pet.itemColors?.[selectedShopItem]||defaultItemColor(selectedShopItem);render();root.querySelector('#close-item')?.focus();});
 root.querySelectorAll('[data-item-color]').forEach(b=>b.onclick=()=>{selectedItemColor=b.dataset.itemColor;render();root.querySelector(`[data-item-color="${selectedItemColor}"]`)?.focus();});
 const close=root.querySelector('#close-item');if(close){const dismiss=()=>{selectedShopItem=null;render();};close.onclick=dismiss;const dialog=root.querySelector('.item-dialog');dialog.onkeydown=e=>{if(e.key==='Escape')dismiss();if(e.key==='Tab'){const buttons=[...dialog.querySelectorAll('button:not(:disabled)')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}};root.querySelector('.item-overlay').onclick=e=>{if(e.target.classList.contains('item-overlay'))dismiss();};}
 const confirm=root.querySelector('#confirm-item');if(confirm)confirm.onclick=()=>{updatePetTime();pet=buy(pet,selectedShopItem,selectedItemColor);audio.sound('buy');save();selectedShopItem=null;shopTab='owned';render();};
}

function notify(text,duration=3500){clearTimeout(notificationTimer);message=text;const el=document.querySelector('.toast');if(el){el.textContent=text;el.classList.add('show');}notificationTimer=setTimeout(()=>{message='';document.querySelector('.toast')?.classList.remove('show');},duration);}
function modal(title,content){document.body.classList.add('modal-open');const el=document.createElement('div');el.className='overlay';el.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-label="${title}"><button class="close" aria-label="Fechar">×</button><p class="eyebrow">BRINCANDO JUNTOS</p><h2>${title}</h2><div id="play">${content}</div></section>`;document.body.append(el);el.querySelector('.close').onclick=async()=>{if(game&&game!=='finished'){if(!await petConfirm('Encerrar partida','Você receberá a recompensa atual. A próxima partida começará do zero, mas seus pontos acumulados e recordes serão mantidos.','Encerrar partida'))return;if(sessionScore>0){finish(sessionScore,['memory','sequence','puzzle','hide','words','blocks','match3','fruitmerge'].includes(game));return;}}cleanup();game=null;sessionScore=0;sessionRounds=0;el.remove();document.body.classList.remove('modal-open');render();};el.querySelector('.close').focus();return el.querySelector('#play');}
function finish(score,smart){if(!game||game==='finished')return;cleanup();const p=pet.coins,intelligenceBefore=pet.stats.intelligence;updatePetTime();pet=reward(pet,score,smart,game);if(['blocks','match3'].includes(game)){const earned=score>0?2+Math.floor(Math.sqrt(score)/10):0;pet.coins=p+earned;pet.lastEarning=earned;}save();const wallet=document.querySelector('.wallet');if(wallet)wallet.innerHTML=`${icon('coin')} ${pet.coins}<small>+${pet.coins-p}</small>`;const area=document.querySelector('#play');area.innerHTML=`<div class="result">${icon('points')}<h2>Boa brincadeira!</h2><p>${Math.round(score)} pontos · +${pet.coins-p} moedas</p><p>${smart?`+${Math.round((pet.stats.intelligence-intelligenceBefore)*10)/10} de inteligência`:pet.dead?'Moedas guardadas para reviver.':'Seu pet ficou mais feliz.'}</p><button class="primary" id="done">Voltar aos jogos</button></div>`;area.querySelector('#done').onclick=()=>{document.querySelector('.overlay').remove();document.body.classList.remove('modal-open');game=null;sessionScore=0;sessionRounds=0;page='games';render();};game='finished';audio.sound('win');}
function start(id){updatePetTime();if(!pet.dead&&pet.stats.energy<10)return notify('Descanse primeiro.');cleanup=()=>{};sessionScore=0;sessionRounds=0;game=id;const area=modal(mini.find(m=>m[0]===id)[2],'');({memory,sequence,food,fruitmerge:startFruitMerge,runner,puzzle,hide,flight:startFlight,words:startWords,blocks:startPrototype,match3:startPrototype}[id])(area);}
function startPrototype(area){document.querySelector('.dialog').classList.add('proto-dialog');cleanup=prototypeGame(game,area,{sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;},onEnd:n=>finish(n,true)});}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function memory(a){const pairs=memoryPairs(sessionRounds),symbols=shuffle(['apple','chicken','leaf','memory-ball','sleep','star','affection','games','bath','health','rocket','sun','coin','memory','energy','medicine','clean','home','shop','bell','points','box','sequence','puzzle','hide','runner','flight','words','egg','settings']).slice(0,pairs),cards=shuffle([...symbols,...symbols]);let opened=[],found=new Set(),turns=0,locked=false;const timeouts=[];cleanup=()=>timeouts.forEach(clearTimeout);a.innerHTML=`<p>${sessionScore} pontos · Rodada ${sessionRounds+1}</p>`+`<div class="memory-board ${pairs>12?'dense':''}" style="--columns:${pairs>8?6:4}">`+cards.map((_,i)=>`<button data-card="${i}" aria-label="Carta ${i+1}">?</button>`).join('')+'</div>';a.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{const i=+b.dataset.card;if(locked||found.has(i)||opened.includes(i))return;b.classList.add('revealed');b.innerHTML=icon(cards[i]==='sleep'?'memoryMoon':cards[i]);opened.push(i);if(opened.length===2){turns++;const [x,y]=opened;if(cards[x]===cards[y]){found.add(x);found.add(y);audio.sound('match');a.querySelector(`[data-card="${x}"]`).classList.add('matched');a.querySelector(`[data-card="${y}"]`).classList.add('matched');opened=[];if(found.size===cards.length)timeouts.push(setTimeout(()=>nextBoard(a,Math.max(20,100-(turns-pairs)*5),memory),500));}else{locked=true;timeouts.push(setTimeout(()=>{a.querySelectorAll('[data-card]').forEach(c=>{if(!found.has(+c.dataset.card)){c.textContent='?';c.classList.remove('revealed');}});opened=[];locked=false;},650));}}});}
function sequence(a){let seq=[],index=0,showing=false,level=0,timers=[];const colors=['#f25587','#ffc536','#32cbb0','#9261ec'];cleanup=()=>timers.forEach(clearTimeout);a.innerHTML='<p id="hint">Observe a sequência.</p><div class="sequence-board">'+colors.map((c,i)=>`<button data-color="${i}" style="background:${c}" aria-label="Cor ${i+1}">${['●','▲','■','★'][i]}</button>`).join('')+'</div>';const buttons=[...a.querySelectorAll('[data-color]')],hint=a.querySelector('#hint');function next(){level++;seq.push(Math.floor(Math.random()*4));index=0;showing=true;hint.textContent=`${sessionScore} pontos · nível ${level}`;seq.forEach((v,k)=>{timers.push(setTimeout(()=>buttons[v].classList.add('flash'),700+k*650));timers.push(setTimeout(()=>buttons[v].classList.remove('flash'),1100+k*650));});timers.push(setTimeout(()=>{showing=false;hint.textContent='Sua vez!';},700+seq.length*650));}buttons.forEach((b,i)=>b.onclick=()=>{if(showing)return;if(i!==seq[index])return finish(sessionScore,true);index++;if(index===seq.length){showing=true;sessionScore+=20;timers.push(setTimeout(next,500));}});next();}
function food(a){document.querySelector('.dialog').classList.add('arcade-dialog');cleanup=arcade('food',a,{spriteSvg:drawing(species.find(s=>s.id===pet.species)),sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;},onEnd:n=>finish(n,false)});}
function startFruitMerge(a){document.querySelector('.dialog').classList.add('fruit-merge-dialog');cleanup=fruitMergeGame(a,{sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;},onEnd:n=>finish(n,true)});}
function runner(a){document.querySelector('.dialog').classList.add('arcade-dialog');cleanup=arcade('runner',a,{spriteSvg:gameSprite(),sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;},onEnd:n=>finish(n,false)});}
function nextBoard(area,points,fn){sessionScore+=points;sessionRounds++;cleanup();fn(area);}
function puzzle(a){const image='data:image/svg+xml,'+encodeURIComponent(drawing(species.find(s=>s.id===pet.species)).replace(/<svg(?![^>]*xmlns=)/, '<svg xmlns="http://www.w3.org/2000/svg"'));let tiles=[1,2,3,4,5,6,7,8,0],moves=0;const adjacent=z=>[z%3>0?z-1:-1,z%3<2?z+1:-1,z>=3?z-3:-1,z<6?z+3:-1].filter(i=>i>=0);for(let k=0;k<60;k++){const z=tiles.indexOf(0),list=adjacent(z),i=list[Math.floor(Math.random()*list.length)];[tiles[z],tiles[i]]=[tiles[i],tiles[z]];}if(tiles.every((v,i)=>v===(i+1)%9)){[tiles[7],tiles[8]]=[tiles[8],tiles[7]];}function draw(){a.innerHTML='<div class="puzzle-board">'+tiles.map((v,i)=>`<button data-tile="${i}" style="background-image:url('${v?image:''}');background-size:300% 300%;background-position:${((v-1)%3)*50}% ${Math.floor((v-1)/3)*50}%" ${!v?'disabled':''}>${v||''}</button>`).join('')+`</div><p>${sessionScore} pontos · ${moves} movimentos</p>`;a.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{const i=+b.dataset.tile,z=tiles.indexOf(0);if(!adjacent(z).includes(i))return;[tiles[z],tiles[i]]=[tiles[i],tiles[z]];moves++;if(tiles.every((v,i)=>v===(i+1)%9))nextBoard(a,Math.max(20,100-Math.max(0,moves-25)),puzzle);else draw();});}draw();}
function hide(a){const petArt=drawing(species.find(x=>x.id===pet.species),'idle');let round=0,points=0,hidden=0,ready=false,order=[0,1,2],stopped=false;const timers=[];cleanup=()=>{stopped=true;timers.forEach(clearTimeout);};const wait=ms=>new Promise(resolve=>timers.push(setTimeout(resolve,ms)));async function next(){round++;hidden=Math.floor(Math.random()*3);order=[0,1,2];ready=false;a.innerHTML=`<p id="hint">${points} pontos · Fase ${round} · observe o pet!</p><div class="shell-board">${order.map(i=>`<button data-shell="${i}" aria-label="Caixa ${i+1}" style="--position:${i}">${i===hidden?petArt:icon('box')}</button>`).join('')}</div>`;await wait(1100);if(stopped)return;a.querySelectorAll('[data-shell]').forEach(b=>b.innerHTML=icon('box'));a.querySelector('#hint').textContent='Acompanhe as caixas…';await wait(400);for(let n=0;n<Math.min(10,3+round);n++){if(stopped)return;const x=Math.floor(Math.random()*3),y=(x+1+Math.floor(Math.random()*2))%3;[order[x],order[y]]=[order[y],order[x]];const duration=Math.max(280,750-round*45);a.querySelectorAll('[data-shell]').forEach(b=>{b.style.transitionDuration=duration+'ms';b.style.setProperty('--position',order.indexOf(+b.dataset.shell));});await wait(duration+100);}if(stopped)return;ready=true;a.querySelector('#hint').textContent='Onde o pet está?';a.querySelectorAll('[data-shell]').forEach(b=>b.onclick=()=>{if(!ready)return;ready=false;const correct=+b.dataset.shell===hidden;b.innerHTML=correct?petArt:icon('box');a.querySelector(`[data-shell="${hidden}"]`).innerHTML=petArt;if(correct){points+=20;sessionScore=points;}audio.sound(correct?'match':'wrong');timers.push(setTimeout(()=>correct?next():finish(points,true),850));});}next();}
setInterval(()=>{if(pet&&!game){updatePetTime();save();if(page==='home'&&activity==='idle'&&root.querySelector('.world')?.dataset.skillBusy!=='true')render();}},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&pet){updatePetTime();save();if(!game)render();}});
render();
reminders.sync(pet);

function startFlight(area){document.querySelector('.dialog').classList.add('arcade-dialog');cleanup=flight(area,{spriteSvg:gameSprite(true),sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;},onEnd:n=>finish(n,false)});}
function startWords(area){document.querySelector('.dialog').classList.add('word-dialog');cleanup=wordSearch(area,{sound:n=>audio.sound(n),onScore:n=>{sessionScore=n;}});}
